-- Customer follow-up only. No website, payment, subscription or customer permissions change.
CREATE TABLE IF NOT EXISTS lifecycle_settings(id boolean PRIMARY KEY DEFAULT true CHECK(id),enabled boolean NOT NULL DEFAULT true,first_days integer NOT NULL DEFAULT 3,second_days integer NOT NULL DEFAULT 7,human_days integer NOT NULL DEFAULT 14,gap_days integer NOT NULL DEFAULT 3,last_scan_at timestamptz,last_dispatch_at timestamptz,updated_at timestamptz NOT NULL DEFAULT now(),CHECK(first_days>=1 AND second_days>first_days AND human_days>second_days AND human_days<=90 AND gap_days BETWEEN 1 AND 30));
INSERT INTO lifecycle_settings(id) VALUES(true) ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS lifecycle_accounts(organization_id uuid PRIMARY KEY REFERENCES organizations(id) ON DELETE CASCADE,stage text NOT NULL CHECK(stage IN('NO_SITE','DRAFT','FREE_DOMAIN','CONNECT_DOMAIN','COMPLETE','MANAGED')),cycle uuid NOT NULL DEFAULT gen_random_uuid(),stage_started_at timestamptz NOT NULL DEFAULT now(),recipient text,paused_until timestamptz,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS lifecycle_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,cycle uuid NOT NULL,stage text NOT NULL,step integer NOT NULL CHECK(step IN(1,2)),recipient text NOT NULL,state text NOT NULL DEFAULT 'QUEUED' CHECK(state IN('QUEUED','SUBMITTING','ACCEPTED','FAILED','UNKNOWN','SUPPRESSED','CANCELLED')),payload jsonb,attempts integer NOT NULL DEFAULT 0,lease_until timestamptz,next_attempt_at timestamptz NOT NULL DEFAULT now(),provider_id text,last_error text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(organization_id,cycle,step));
CREATE UNIQUE INDEX IF NOT EXISTS lifecycle_recipient_claim ON lifecycle_events(recipient) WHERE state='SUBMITTING';
CREATE TABLE IF NOT EXISTS lifecycle_handoffs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,cycle_key text NOT NULL,reason text NOT NULL,status text NOT NULL DEFAULT 'OPEN' CHECK(status IN('OPEN','IN_PROGRESS','DONE')),assigned_to uuid REFERENCES admin_users(id) ON DELETE SET NULL,follow_up_on date,notes text NOT NULL DEFAULT '' CHECK(length(notes)<=2000),revision integer NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(organization_id,cycle_key));
CREATE TABLE IF NOT EXISTS lifecycle_audit(id bigserial PRIMARY KEY,actor_id text NOT NULL,event text NOT NULL,organization_id uuid REFERENCES organizations(id) ON DELETE SET NULL,detail jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE OR REPLACE VIEW lifecycle_current AS
SELECT o.id organization_id,COALESCE(NULLIF(b.display_name,''),o.name,'Business account') business_name,lower(owner.email) recipient,
 CASE WHEN EXISTS(SELECT 1 FROM custom_clients cc WHERE cc.organization_id=o.id) THEN 'MANAGED'
 WHEN b.published=true AND COALESCE(b.custom_domain,'')<>'' AND b.custom_domain_verified=true THEN 'COMPLETE'
 WHEN b.published=true AND(COALESCE(b.custom_domain,'')<>'' OR EXISTS(SELECT 1 FROM domain_assets d WHERE d.organization_id=o.id AND d.expires_at>now())) THEN 'CONNECT_DOMAIN'
 WHEN b.published=true THEN 'FREE_DOMAIN'
 WHEN COALESCE(b.website_template_id,'')<>'' OR COALESCE(b.website_document,'{}'::jsonb)<>'{}'::jsonb THEN 'DRAFT' ELSE 'NO_SITE' END stage,
 EXISTS(SELECT 1 FROM domain_assets d WHERE d.organization_id=o.id AND d.expires_at>now()) OR COALESCE(b.custom_domain,'')<>'' has_domain
FROM organizations o LEFT JOIN business_profiles b ON b.organization_id=o.id
LEFT JOIN LATERAL(SELECT COALESCE(NULLIF(u.email,''),NULLIF(m.email,'')) email FROM organization_members m JOIN users u ON u.id=m.user_id WHERE m.organization_id=o.id AND m.role='owner' AND m.active=true AND to_jsonb(u)->>'disabled_at' IS NULL AND to_jsonb(u)->>'deleted_at' IS NULL ORDER BY m.created_at,m.id LIMIT 1)owner ON true
WHERE COALESCE(o.slug,'')<>'demo' AND COALESCE(to_jsonb(o)->>'is_demo','false')<>'true' AND EXISTS(SELECT 1 FROM organization_members registered JOIN users active_user ON active_user.id=registered.user_id WHERE registered.organization_id=o.id AND registered.role='owner' AND registered.active=true AND to_jsonb(active_user)->>'disabled_at' IS NULL AND to_jsonb(active_user)->>'deleted_at' IS NULL);
